# viscosity: ps=soa
from array import array as _vsc_array
# Generated by Viscosity: bounds check matching list's IndexError.
def _vsc_ix(c, i):
    if -c.n <= i < c.n:
        return i
    raise IndexError('list index out of range')
# Generated by Viscosity: like iterating a list, re-checks the length each step.
def _vsc_iter(c):
    i = 0
    while i < c.n:
        yield i
        i += 1
# Generated by Viscosity: "ps" stored as a struct of arrays (fields x, y, vx, vy, name).
class _Vsc_ps:
    __slots__ = ('n', 'x', 'y', 'vx', 'vy', 'name')
    def __init__(self):
        self.n = 0
        self.x = _vsc_array('d')
        self.y = _vsc_array('d')
        self.vx = _vsc_array('d')
        self.vy = _vsc_array('d')
        self.name = []
    def append(self, v0, v1, v2, v3, v4):
        self.x.append(v0)
        self.y.append(v1)
        self.vx.append(v2)
        self.vy.append(v3)
        self.name.append(v4)
        self.n += 1
    def __len__(self):
        return self.n
    @classmethod
    def _of(cls, *v):
        c = cls()
        for i in range(0, len(v), 5):
            c.append(v[i + 0], v[i + 1], v[i + 2], v[i + 3], v[i + 4])
        return c

from dataclasses import dataclass
import math

@dataclass
class Particle:
    x: float
    y: float
    vx: float
    vy: float
    name: str

ps = _Vsc_ps()
for i in range(2000):
    ps.append(i * 0.5, 0.0, 1.0, -1.0, "p" + str(i))

def step(arr, dt):
    for i in range(len(arr)):
        p = i
        arr.x[p] += arr.vx[p] * dt
    for q in _vsc_iter(arr):
        arr.y[q] = arr.y[q] + arr.vy[q] * dt

for k in range(10):
    step(ps, 0.016)
total = 0.0
for p in _vsc_iter(ps):
    total += math.sqrt(ps.x[p] * ps.x[p] + ps.y[p] * ps.y[p])
print(round(total, 6), ps.name[3], ps.x[1999], len(ps))
